SELECT *
FROM chat_message
WHERE session_id = #{sessionId}
ORDER BY seq_no DESC
LIMIT #{limit}

SELECT *
FROM chat_message
WHERE session_id = #{sessionId}
  AND seq_no < #{beforeSeqNo}
ORDER BY seq_no DESC
LIMIT #{limit}

SELECT COALESCE(MAX(seq_no), 0)
FROM chat_message
WHERE session_id = #{sessionId}

mapper.update:
UPDATE chat_message
SET status = #{targetStatus}
WHERE id = #{messageId}
  AND status = #{expectedStatus}
